import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { Pool, type Connection } from "../src/db/pool.ts";
import { ShipmentService } from "../src/tracking/shipments.ts";
import { ingestScanBatch } from "../src/tracking/ingest.ts";
import type { ScanEvent } from "../src/tracking/status.ts";

// In-memory "database" behind fake connections. Every query yields, like a network round trip.
function setup(poolSize: number, trackingNos: string[]) {
    const shipments = new Map(trackingNos.map((t) => [t, { status: "label_created" as string }]));
    const events: ScanEvent[] = [];
    const connect = (): Connection => ({
        async query<T>(sql: string, params: unknown[]): Promise<T[]> {
            await tick();
            const no = params[0] as string;
            if (sql.startsWith("SELECT tracking_no FROM shipments")) return (shipments.has(no) ? [{ tracking_no: no }] : []) as T[];
            if (sql.startsWith("SELECT status FROM shipments")) return (shipments.has(no) ? [{ status: shipments.get(no)!.status }] : []) as T[];
            if (sql.startsWith("INSERT INTO scan_events")) {
                const [trackingNo, type, location, scannedAt] = params as string[];
                events.push({ trackingNo, type: type as ScanEvent["type"], location, scannedAt });
                return [];
            }
            if (sql.startsWith("SELECT * FROM scan_events")) {
                return events.filter((e) => e.trackingNo === no).sort((a, b) => a.scannedAt.localeCompare(b.scannedAt)) as T[];
            }
            if (sql.startsWith("UPDATE shipments")) {
                shipments.get(no)!.status = params[1] as string;
                return [];
            }
            throw new Error(`unexpected query: ${sql}`);
        },
    });
    const pool = new Pool(poolSize, connect);
    return { pool, service: new ShipmentService(pool), shipments };
}

async function within<T>(ms: number, work: Promise<T>): Promise<T> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error(`still waiting after ${ms}ms (pool exhausted?)`)), ms);
    });
    try {
        return await Promise.race([work, timeout]);
    } finally {
        clearTimeout(timer);
    }
}

const scan = (trackingNo: string, type: ScanEvent["type"], minute: number): ScanEvent => ({
    trackingNo,
    type,
    location: "RTM-HUB",
    scannedAt: `2026-11-19T08:${String(minute).padStart(2, "0")}:00Z`,
});

test("a scan is stored and the shipment status follows the scan history", async () => {
    const { service } = setup(4, ["PK100"]);
    assert.equal(await within(500, service.recordScan(scan("PK100", "picked_up", 1))), "in_transit");
    assert.equal(await within(500, service.recordScan(scan("PK100", "out_for_delivery", 30))), "out_for_delivery");
    // a late upload from earlier in the route doesn't move the parcel backwards
    await within(500, service.recordScan(scan("PK100", "arrived_hub", 10)));
    const tracking = await service.getTracking("PK100");
    assert.equal(tracking?.status, "out_for_delivery");
    assert.deepEqual(tracking?.events.map((e) => e.type), ["picked_up", "arrived_hub", "out_for_delivery"]);
});

test("recording a scan holds at most one connection at a time", async () => {
    const { pool, service } = setup(4, ["PK100"]);
    await within(500, service.recordScan(scan("PK100", "picked_up", 1)));
    console.log("connections checked out at once during one scan:", pool.maxCheckedOut);
    assert.equal(pool.maxCheckedOut, 1);
    assert.equal(pool.inUse, 0);
});

test("as many simultaneous scans as the pool has connections all complete", async () => {
    const { service, shipments } = setup(2, ["PK1", "PK2"]);
    await within(1000, Promise.all([service.recordScan(scan("PK1", "picked_up", 1)), service.recordScan(scan("PK2", "delivered", 2))]));
    assert.deepEqual([shipments.get("PK1")?.status, shipments.get("PK2")?.status], ["in_transit", "delivered"]);
});

test("a hub upload bigger than the pool is ingested without stalling", async () => {
    const nos = Array.from({ length: 12 }, (_, i) => `PK${200 + i}`);
    const { pool, service } = setup(4, nos);
    const result = await within(1500, ingestScanBatch(service, nos.map((n, i) => scan(n, "arrived_hub", i)), 4));
    assert.deepEqual(result, { recorded: 12, rejected: [] });
    assert.ok(pool.maxCheckedOut <= 4);
});

test("an unknown tracking number is rejected and its connection goes back to the pool", async () => {
    const { pool, service } = setup(1, ["PK100"]);
    await assert.rejects(service.recordScan(scan("NOPE", "picked_up", 1)), /unknown tracking number NOPE/);
    assert.equal(pool.inUse, 0);
    assert.equal(await service.getTracking("NOPE"), null);
});

test("ops can recalculate a shipment's status on demand", async () => {
    const { service, shipments } = setup(2, ["PK100"]);
    shipments.get("PK100")!.status = "delivered";
    assert.equal(await within(500, service.refreshStatus("PK100")), "label_created");
});
